102		// Every rule re-reads with exactly the fields the input grammar allows.
103		cfg := mustConfig(t, `{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h",
104		  "queryTransforms":[
105		    {"op":"set","name":"a","value":""},
106		    {"op":"remove","name":"b"},
