108		    {"op":"copy","name":"e","to":"f"}
109		  ]}]}`)
110		var doc struct {
111			Routes []struct {
112				Rules []map[string]json.RawMessage `json:"queryTransforms"`
113			} `json:"routes"`
114		}
115		if err := json.Unmarshal(mustMarshal(t, cfg), &doc); err != nil {
116			t.Fatal(err)
117		}
