119			{"op": true, "name": true, "value": true}, // set keeps value even when empty
120			{"op": true, "name": true},                // remove: no value, no to
121			{"op": true, "name": true, "to": true},    // rename: to, no value
122			{"op": true, "name": true, "to": true},    // copy: to, no value
123		}
124		for i, rule := range doc.Routes[0].Rules {
125			if len(rule) != len(wantKeys[i]) {
126				t.Fatalf("rule %d keys = %v, want %v", i, keysOf(rule), wantKeys[i])
127			}
