178	func TestInvalidConfigsRemainRejectedAfterMarshalCode(t *testing.T) {
179		// The save path must not change read-side validation.
180		for _, src := range []string{
181			`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":null}]}`,
182			`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"remove","name":"a","value":"x"}]}]}`,
183			`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"rename","name":"a","value":"x","to":"b"}]}]}`,
184			`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"rename","name":"a","to":""}]}]}`,
185			`{"routes":null}`,
186		} {
187			if _, f := ParseConfig([]byte(src)); f == nil || f.Code != "invalid_config" {
188				t.Fatalf("expected invalid_config for %s, got %v", src, f)
189			}
190		}
191	}
192	
193	func mustMarshal(t *testing.T, v any) []byte {
194		t.Helper()
195		out, err := json.Marshal(v)
196		if err != nil {
197			t.Fatal(err)
198		}
