1	package contractsentinel
2	
3	import (
4		"encoding/json"
5		"sort"
6		"testing"
7	)
8	
9	// These tests guard conflict adjudication across the public save/reload
10	// path: a config parsed through ParseConfig is written with the standard
11	// library's encoding/json and read back through the same ParseConfig that
12	// production readers use, and the reloaded config is then actually used to
13	// resolve requests. Saving must not change which routes compete: a
14	// pre-save route_conflict may neither become a success nor flip to
15	// invalid_config, and a pre-save success must keep the same route id and
16	// the same fully-joined upstream URL (raw query included).
17	//
18	// Every scenario is exercised both before and after the save and with the
19	// routes declared in two orders, so candidate ordering in the saved output
20	// cannot mask a change in who competes.
21	
22	// saveAndReparse runs one parsed config through the public save path:
23	// encoding/json marshals it the way an application saves it, and the
24	// existing ParseConfig reader parses the result. The saved document is a
25	// legal config rather than merely legal JSON; a re-read failure (in
26	// particular invalid_config) fails the test.
27	func saveAndReparse(t *testing.T, cfg *Config) *Config {
28		t.Helper()
29		out, err := json.Marshal(cfg)
30		if err != nil {
31			t.Fatalf("marshal config: %v", err)
32		}
33		saved, f := ParseConfig(out)
34		if f != nil {
35			t.Fatalf("saved config rejected on re-read: %v\n%s", f, out)
36		}
37		return saved
38	}
39	
40	// resolveOutcome is the complete observable result of one resolution:
41	// exactly one of res and fail is set.
42	type resolveOutcome struct {
43		res  *Resolution
44		fail *Failure
45	}
46	
47	func resolveFor(t *testing.T, cfg *Config, method, target string) resolveOutcome {
48		t.Helper()
49		res, f := Resolve(cfg, mustReq(t, method, target))
50		return resolveOutcome{res: res, fail: f}
51	}
52	
53	// expectSuccess requires a resolution to succeed on the given config with
54	// exactly the expected route id and upstream URL. A conflict or any other
55	// failure — including a wrongly rejected config upstream of resolution —
56	// fails here.
57	func expectSuccess(t *testing.T, label, method, target, wantID, wantURL string, cfg *Config) {
58		t.Helper()
59		out := resolveFor(t, cfg, method, target)
60		if out.fail != nil {
61			t.Fatalf("%s: %s %s failed with %s: %s", label, method, target, out.fail.Code, out.fail.Reason)
62		}
63		if out.res == nil {
64			t.Fatalf("%s: %s %s returned neither resolution nor failure", label, method, target)
65		}
66		if out.res.RouteID != wantID {
67			t.Fatalf("%s: %s %s routeId = %q, want %q", label, method, target, out.res.RouteID, wantID)
68		}
69		if out.res.UpstreamURL != wantURL {
70			t.Fatalf("%s: %s %s upstreamURL = %q, want %q", label, method, target, out.res.UpstreamURL, wantURL)
71		}
72	}
73	
74	// expectConflict requires route_conflict at request-resolution time (never
75	// invalid_config), a non-empty reason, no successful resolution and an
76	// exact, lexicographically sorted candidate list. An exact-list assertion
77	// also proves every route already eliminated by prefix length or
78	// concrete-vs-wildcard is absent.
79	func expectConflict(t *testing.T, label, method, target string, wantCandidates []string, cfg *Config) {
80		t.Helper()
81		out := resolveFor(t, cfg, method, target)
82		if out.res != nil {
83			t.Fatalf("%s: %s %s resolved to %+v, want route_conflict", label, method, target, out.res)
84		}
85		if out.fail == nil {
86			t.Fatalf("%s: %s %s returned no failure, want route_conflict", label, method, target)
87		}
88		if out.fail.Code != "route_conflict" {
89			t.Fatalf("%s: %s %s code = %q, want route_conflict (saving must not turn a request-stage conflict into a config error)",
90				label, method, target, out.fail.Code)
91		}
92		if out.fail.Reason == "" {
93			t.Fatalf("%s: %s %s route_conflict carries no reason", label, method, target)
94		}
95		if !equalStrings(out.fail.Candidates, wantCandidates) {
96			t.Fatalf("%s: %s %s candidates = %v, want %v", label, method, target, out.fail.Candidates, wantCandidates)
97		}
98		if !sort.StringsAreSorted(out.fail.Candidates) {
99			t.Fatalf("%s: %s %s candidates %v are not in lexicographic order", label, method, target, out.fail.Candidates)
100		}
101	}
102	
103	// assertSameOutcome fails unless two outcomes are the same kind of result
104	// with identical observable content, so the before/after comparison below
105	// is a complete equality check rather than two independent expectations.
106	func assertSameOutcome(t *testing.T, method, target string, before, after resolveOutcome) {
107		t.Helper()
108		switch {
109		case before.fail != nil || after.fail != nil:
110			if before.fail == nil || after.fail == nil {
111				t.Fatalf("%s %s changed success/failure kind across save: before=%+v after=%+v",
112					method, target, before.res, after.fail)
113			}
114			if before.fail.Code != after.fail.Code {
115				t.Fatalf("%s %s error code changed across save: %q vs %q", method, target, before.fail.Code, after.fail.Code)
116			}
117			if !equalStrings(before.fail.Candidates, after.fail.Candidates) {
118				t.Fatalf("%s %s candidates changed across save: %v vs %v",
119					method, target, before.fail.Candidates, after.fail.Candidates)
120			}
121			if (before.fail.Reason == "") != (after.fail.Reason == "") {
122				t.Fatalf("%s %s reason presence changed across save", method, target)
123			}
124		case before.res == nil || after.res == nil:
125			t.Fatalf("%s %s missing a resolution on one side", method, target)
126		default:
127			if before.res.RouteID != after.res.RouteID || before.res.UpstreamURL != after.res.UpstreamURL {
128				t.Fatalf("%s %s success changed across save:\n before %+v\n after  %+v",
129					method, target, before.res, after.res)
130			}
131		}
132	}
133	
134	func TestSaveRoundTripLongestWildcardBeatsShorterConflict(t *testing.T) {
135		// Two concrete GET routes share the shorter prefix /a; one wildcard
136		// route owns the longer prefix /a/b. Inside the longer prefix the
137		// wildcard must win both before and after saving — the two short GET
138		// routes must not reject the request as their conflict, and a concrete
139		// GET on the shorter prefix must not outrank a wildcard on the longer
140		// one. A request that reaches only /a must keep conflicting on exactly
141		// the two short routes.
142		routes := []string{
143			`{"id":"short-one","methods":["GET"],"pathPrefix":"/a","upstream":"http://one.internal/s1"}`,
144			`{"id":"short-two","methods":["GET"],"pathPrefix":"/a","upstream":"http://two.internal/s2"}`,
145			`{"id":"long-wild","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal/base"}`,
146		}
147	
148		// Duplicate parameters, an empty value and percent escapes (including
149		// an encoded '&' that must never split the query) survive both route
150		// selection and the save.
151		deepTarget := "/a/b/c/items?dup=1&dup=2&empty=&raw=%2f%41&%26=x"
152		deepUpstream := "http://wild.internal/base/c/items?dup=1&dup=2&empty=&raw=%2f%41&%26=x"
153	
154		for _, order := range [][]string{routes, reversed(routes)} {
155			cfg := mustConfig(t, configFromRoutes(order...))
156			saved := saveAndReparse(t, cfg)
157	
158			// Direct expectations on both sides: candidate set, error code and
159			// successful id/upstream all stay stable through the save.
160			for _, v := range []struct {
161				label string
162				cfg   *Config
163			}{
164				{"before save", cfg},
165				{"after save", saved},
166			} {
167				expectSuccess(t, v.label, "GET", deepTarget, "long-wild", deepUpstream, v.cfg)
168				expectSuccess(t, v.label, "GET", "/a/b", "long-wild", "http://wild.internal/base/", v.cfg)
169				// Same longer-prefix wildcard serves other methods too.
170				expectSuccess(t, v.label, "POST", "/a/b/c", "long-wild", "http://wild.internal/base/c", v.cfg)
171				// Only the short prefix matches: its two concrete GET routes
172				// conflict, and the longer-prefix wildcard is not a candidate.
173				expectConflict(t, v.label, "GET", "/a/only?z=1", []string{"short-one", "short-two"}, v.cfg)
174			}
175	
176			// Whole-outcome equality is the actual save-regression assertion.
177			for _, req := range []struct{ method, target string }{
178				{"GET", deepTarget},
179				{"GET", "/a/b"},
180				{"POST", "/a/b/c"},
181				{"GET", "/a/only?z=1"},
182			} {
183				assertSameOutcome(t, req.method, req.target,
184					resolveFor(t, cfg, req.method, req.target),
185					resolveFor(t, saved, req.method, req.target))
186			}
187		}
188	}
189	
190	func TestSaveRoundTripConflictCandidatesStayExact(t *testing.T) {
191		// The longest matching prefix /a/b carries two concrete GET routes and
192		// a wildcard route; a shorter concrete GET route sits at /a. For a GET
193		// request at /a/b the two concrete routes conflict: the saved config
194		// must keep failing, list only those two routes sorted lexicographically,
195		// and omit the already-excluded same-prefix wildcard and shorter-prefix
196		// route. POST has no concrete rival at /a/b and must succeed on the
197		// wildcard regardless of the GET conflict — both before and after saving.
198		//
199		// The routes are deliberately declared in an order different from
200		// lexicographic (zeta before alpha), so a passing result proves the
201		// existing sort rule rather than config order; the reversed slice
202		// proves order independence again after the save.
203		routes := []string{
204			`{"id":"z-short","methods":["GET"],"pathPrefix":"/a","upstream":"http://short.internal"}`,
205			`{"id":"wild-long","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal/w"}`,
206			`{"id":"zeta","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://z.internal"}`,
207			`{"id":"alpha","methods":["GET"],"pathPrefix":"/a/b","upstream":"http://a.internal"}`,
208		}
209	
210		for _, order := range [][]string{routes, reversed(routes)} {
211			cfg := mustConfig(t, configFromRoutes(order...))
212			saved := saveAndReparse(t, cfg)
213	
214			for _, v := range []struct {
215				label string
216				cfg   *Config
217			}{
218				{"before save", cfg},
219				{"after save", saved},
220			} {
221				// GET stays a request-stage conflict on exactly the two
222				// concrete routes; the wildcard and the shorter route are gone.
223				expectConflict(t, v.label, "GET", "/a/b/x", []string{"alpha", "zeta"}, v.cfg)
224	
225				// A method with no concrete competition wins the longest-prefix
226				// wildcard; the GET conflict must not poison it.
227				expectSuccess(t, v.label, "POST", "/a/b/x", "wild-long", "http://wild.internal/w/x", v.cfg)
228	
229				// The shorter-prefix concrete route still serves requests that
230				// never reach the conflicted prefix.
231				expectSuccess(t, v.label, "GET", "/a/other", "z-short", "http://short.internal/other", v.cfg)
232			}
233	
234			for _, req := range []struct{ method, target string }{
235				{"GET", "/a/b/x"},
236				{"POST", "/a/b/x"},
237				{"GET", "/a/other"},
238			} {
239				assertSameOutcome(t, req.method, req.target,
240					resolveFor(t, cfg, req.method, req.target),
241					resolveFor(t, saved, req.method, req.target))
242			}
243		}
244	}
245	
246	func TestSaveRoundTripConflictDoesNotBecomeConfigError(t *testing.T) {
247		// A focused guard for the specific regression shape named in the task:
248		// resolving a legal request against a legal reloaded config must fail at
249		// the request stage with route_conflict — never invalid_config — whether
250		// or not the request carries a query string.
251		cfg := mustConfig(t, configFromRoutes(
252			`{"id":"short-one","methods":["GET"],"pathPrefix":"/a","upstream":"http://one.internal/s1"}`,
253			`{"id":"short-two","methods":["GET"],"pathPrefix":"/a","upstream":"http://two.internal/s2"}`,
254			`{"id":"long-wild","methods":["*"],"pathPrefix":"/a/b","upstream":"http://wild.internal/base"}`,
255		))
256		saved := saveAndReparse(t, cfg)
257	
258		for _, target := range []string{"/a/only", "/a/only?dup=1&dup=2&e=&p=%2f%41"} {
259			out := resolveFor(t, saved, "GET", target)
260			if out.res != nil {
261				t.Fatalf("GET %s resolved to %+v after save, want route_conflict", target, out.res)
262			}
263			if out.fail == nil {
264				t.Fatalf("GET %s produced no failure after save", target)
265			}
266			if out.fail.Code == "invalid_config" {
267				t.Fatalf("GET %s became invalid_config (%s) after save; conflicts stay request-stage",
268					target, out.fail.Reason)
269			}
270			if out.fail.Code != "route_conflict" {
271				t.Fatalf("GET %s code = %q, want route_conflict", target, out.fail.Code)
272			}
273			if out.fail.Reason == "" {
274				t.Fatalf("GET %s conflict has no reason after save", target)
275			}
276			if !equalStrings(out.fail.Candidates, []string{"short-one", "short-two"}) {
277				t.Fatalf("GET %s candidates = %v after save, want [short-one short-two]",
278					target, out.fail.Candidates)
279			}
280		}
281	}
