cat > /tmp/check.go <<'EOF'
package main

import (
	"encoding/json"
	"fmt"

	cs "github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

func main() {
	bads := []string{
		`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"remove","name":"a","value":"x"}]}]}`,
		`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"rename","name":"a"}]}]}`,
		`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"copy","name":"a","value":"1","to":"b"}]}]}`,
		`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"set","name":"a"}]}]}`,
		`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"copy","name":"a","to":""}]}]}`,
		`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"frob","name":"a"}]}]}`,
	}
	for _, src := range bads {
		_, f := cs.ParseConfig([]byte(src))
		fmt.Println(f.Code+":", f.Reason)
	}
	// set/remove carrying a useless to: accepted, saved without it.
	cfg, f := cs.ParseConfig([]byte(`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h","queryTransforms":[{"op":"set","name":"a","value":"","to":"ignored"},{"op":"remove","name":"b","to":"ignored"}]}]}`))
	if f != nil {
		fmt.Println("unexpected reject:", f)
		return
	}
	out, _ := json.Marshal(cfg)
	fmt.Println(string(out))
}
EOF
go run /tmp/check.go
